# E39_summarise -- power of q = 2 and q = 3 (both chi2_{G-2}) and the bootstrap on E30's data, with paired differences.
# Fingerprint: E39's q2_exact against E30's stored cav_hl (same data, same test). Writes results/E39_power_summary.csv,
# results/E39_power_table.tex (booktabs), results/E39_summary.log.
HERE <- dirname(normalizePath(sub("--file=", "", grep("--file=", commandArgs(), value = TRUE)[1]))); ROOT <- dirname(HERE); RES <- file.path(ROOT, "results")
q <- read.csv(file.path(RES, "E39_power_q3_perrep.csv")); q <- q[!duplicated(q[, c("cell", "dep", "rel", "rep")]), ]
q$q3_repaired <- FALSE      # q = 3 statistics recomputed by E42 where cav_lognormal() stopped (singular information matrix)
if (file.exists(file.path(RES, "E42_q3_repair.csv"))) { rp <- read.csv(file.path(RES, "E42_q3_repair.csv")); rp <- rp[rp$source == "E39", ]
  for (k in seq_len(nrow(rp))) { i <- which(q$cell == rp$cell[k] & q$dep == rp$dep[k] & q$rel == rp$rel[k] & q$rep == rp$rep[k] & is.na(q$q3_chi2G2))
    q$q3_chi2G2[i] <- rp$q3_chi2G2[k]; q$q3_repaired[i] <- TRUE } }
e30 <- read.csv(file.path(RES, "E30_power_strong_perrep.csv"))
m <- merge(q, e30, by = c("cell", "dep", "rel", "rep"))
bt <- if (file.exists(file.path(RES, "E39_power_boot_perrep.csv"))) read.csv(file.path(RES, "E39_power_boot_perrep.csv")) else NULL
if (!is.null(bt)) { bt <- bt[!duplicated(bt[, c("cell", "dep", "rel", "rep")]), ]; m <- merge(m, bt, by = c("cell", "dep", "rel", "rep"), all.x = TRUE) }
sink(file.path(RES, "E39_summary.log"), split = TRUE)
cat(sprintf("Fingerprint: max |q2_exact (E39) - cav_hl (E30)| = %.3g over %d replicates; decisions at .05 that differ: %d\n",
            max(abs(m$q2_exact - m$cav_hl)), nrow(m), sum((m$q2_exact < .05) != (m$cav_hl < .05))))
pr <- function(v) { v <- v[!is.na(v)]; c(mean(v < .05), sqrt(mean(v < .05) * (1 - mean(v < .05)) / length(v))) }
pdiff <- function(a, b) { ok <- !is.na(a) & !is.na(b); dd <- (a[ok] < .05) - (b[ok] < .05); c(mean(dd), sd(dd) / sqrt(length(dd))) }
agg <- do.call(rbind, lapply(split(m, list(m$cell, m$dep, m$rel), drop = TRUE), function(s) {
  o <- data.frame(cell = s$cell[1], dep = s$dep[1], rel = s$rel[1], R = nrow(s), q3_failed = sum(is.na(s$q3_chi2G2)), q3_repaired = sum(s$q3_repaired))
  for (t in c("q2_chi2", "q2_exact", "q3_chi2G2", "calm_hl", "cav_e3")) { z <- pr(s[[t]]); o[[t]] <- z[1]; o[[paste0(t, "_se")]] <- z[2] }
  z <- pdiff(s$q3_chi2G2, s$q2_chi2); o$q3_minus_q2 <- z[1]; o$q3_minus_q2_se <- z[2]
  if (!is.null(bt) && any(!is.na(s$pp_hl))) { z <- pr(s$pp_hl); o$boot_hl <- z[1]; o$boot_hl_se <- z[2]; o$R_boot <- sum(!is.na(s$pp_hl))
    z <- pr(s$pp_edge); o$boot_edge <- z[1]; z <- pdiff(s$q2_chi2, s$pp_hl); o$q2_minus_boot <- z[1]; o$q2_minus_boot_se <- z[2]
    z <- pdiff(s$q3_chi2G2, s$pp_hl); o$q3_minus_boot <- z[1]; o$q3_minus_boot_se <- z[2] } else {
    o$boot_hl <- NA; o$boot_hl_se <- NA; o$R_boot <- 0; o$boot_edge <- NA; o$q2_minus_boot <- NA; o$q2_minus_boot_se <- NA; o$q3_minus_boot <- NA; o$q3_minus_boot_se <- NA }
  o }))
agg <- agg[order(match(agg$cell, c("A_p5", "B_p40", "B_p100")), match(agg$dep, c("cubic", "quadratic", "interaction")), agg$rel), ]
write.csv(agg, file.path(RES, "E39_power_summary.csv"), row.names = FALSE)
options(width = 250); print(agg[, c("cell", "dep", "rel", "R", "q3_failed", "q3_repaired", "q2_chi2", "q2_exact", "q3_chi2G2", "q3_minus_q2", "q3_minus_q2_se",
                                    "calm_hl", "boot_hl", "boot_edge", "R_boot", "q2_minus_boot", "q2_minus_boot_se", "q3_minus_boot", "q3_minus_boot_se")], digits = 3, row.names = FALSE)
f3 <- function(x) if (is.na(x)) "--" else sprintf("%.3f", x)
fd <- function(x, se) if (is.na(x)) "--" else sprintf("%+.3f (%.3f)", x, se)
DL <- c(A_p5 = "A, fixed $p$", B_p40 = "B, $p/n = 0.10$", B_p100 = "B, $p/n = 0.25$")
s15 <- agg[agg$rel == 1.5, ]
lines <- c("% generated by sims/E39_summarise.R -- power at departure size 1.5 (E30 data), 500 replicates; chi2_8 reference for both cavity tests",
           "\\begin{tabular}{llrrrrrr}", "\\toprule",
           " & & \\multicolumn{3}{c}{cavity decile} & & \\multicolumn{2}{c}{bootstrap} \\\\", "\\cmidrule(lr){3-5}\\cmidrule(lr){7-8}",
           "Design & departure & $q=2$ & $q=3$ & $q=3$ minus $q=2$ & in-sample & decile & smooth \\\\", "\\midrule")
for (k in seq_len(nrow(s15))) { z <- s15[k, ]
  lines <- c(lines, sprintf("%s & %s & %s & %s & %s & %s & %s & %s \\\\", if (k == 1 || s15$cell[k] != s15$cell[k - 1]) DL[[z$cell]] else "",
                            z$dep, f3(z$q2_chi2), f3(z$q3_chi2G2), fd(z$q3_minus_q2, z$q3_minus_q2_se), f3(z$calm_hl), f3(z$boot_hl), f3(z$boot_edge))) }
lines <- c(lines, "\\bottomrule", "\\end{tabular}")
writeLines(lines, file.path(RES, "E39_power_table.tex"))
sink()
